const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Wuhan, China region
  const wuhanPoint = ee.Geometry.Point([114.31, 30.59]);
  const wuhanRegion = wuhanPoint.buffer(50000); // 50km buffer

  // Define date ranges
  const feb2019Start = '2019-02-01';
  const feb2019End = '2019-02-28';
  const feb2020Start = '2020-02-01';
  const feb2020End = '2020-02-29';

  // Try MERRA-2 PM2.5 data (if available)
  // GEE doesn't have direct PM2.5, so use MODIS AOD as proxy

  // Attempt 1: MODIS Aerosol Optical Depth (AOD) - proxy for PM2.5
  let col2019 = ee.ImageCollection('MODIS/006/MOD08_M3')
    .filterDate(feb2019Start, feb2019End)
    .filterBounds(wuhanRegion)
    .select('Aerosol_Optical_Depth_3km_Best_Estimate');

  let col2020 = ee.ImageCollection('MODIS/006/MOD08_M3')
    .filterDate(feb2020Start, feb2020End)
    .filterBounds(wuhanRegion)
    .select('Aerosol_Optical_Depth_3km_Best_Estimate');

  const size2019 = col2019.size().getInfo();
  const size2020 = col2020.size().getInfo();

  print(`Feb 2019 Images: ${size2019}`);
  print(`Feb 2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    print('No data for one or both periods');
    print('C1');
    return;
  }

  // Mosaic and calculate mean AOD for each period
  const img2019 = col2019.mosaic();
  const img2020 = col2020.mosaic();

  // Check valid pixels
  const count2019 = img2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wuhanRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('Aerosol_Optical_Depth_3km_Best_Estimate').getInfo();

  const count2020 = img2020.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wuhanRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('Aerosol_Optical_Depth_3km_Best_Estimate').getInfo();

  if (count2019 === 0 || count2020 === 0) {
    print('No valid pixels after processing');
    print('C2');
    return;
  }

  // Calculate mean AOD (proxy for PM2.5)
  const aod2019 = img2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wuhanRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('Aerosol_Optical_Depth_3km_Best_Estimate').getInfo();

  const aod2020 = img2020.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wuhanRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('Aerosol_Optical_Depth_3km_Best_Estimate').getInfo();

  print(`Feb 2019 Mean AOD: ${aod2019}`);
  print(`Feb 2020 Mean AOD: ${aod2020}`);
  print(`Valid Pixels 2019: ${count2019}, 2020: ${count2020}`);

  // Validation
  if (aod2019 === null || aod2020 === null || isNaN(aod2019) || isNaN(aod2020)) {
    print('C3');
    return;
  }

  if (aod2019 < 0 || aod2020 < 0) {
    print('C3');
    return;
  }

  // Compare: Higher AOD in Feb 2020 indicates higher PM2.5
  if (aod2020 > aod2019) {
    print('Feb 2020 had higher AOD than Feb 2019');
    print('A');
  } else {
    print('Feb 2020 had equal or lower AOD than Feb 2019');
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
